/*!
 * Two Squares — "The build" (index-build.html, version B of the home walk).
 * partials/build.html (generated by tools/build_layers.py from assets/data/build.json) + assets/css/build.css.
 * Loads after motion.js, site.js and cafe-seq.js.
 *
 * Each venue is a tall track with a sticky 100svh stage (no ScrollTrigger pin) and ONE scrubbed
 * timeline: 01 the drawing (plan strokes draw themselves) → 02 the sketch (paper, the ruler's lines,
 * then the pencil drawing) → 03 the shell (white model, structure first) → 04 materials (finishes,
 * region by region) → 05 furniture & fittings (each piece drops into place) → 06 lights on (the
 * lamps come up, the room warms) → 07 open (the real photograph, the end title and its action).
 * Every layer is a rendering of the same photograph, so they line up to the pixel.
 *
 * Only opacity, transform and clip-path move. Layers load (and decode) a screen ahead, and are
 * released two screens behind; what's finished and covered stops painting (data-past).
 * Reduced motion: nothing here runs; CSS shows each venue as a drawing / shell / finished spread.
 */
(function (w, d) {
  "use strict";
  const M = w.Motion;
  if (!M || !w.gsap || !w.ScrollTrigger) return;
  const gsap = w.gsap, ST = w.ScrollTrigger;
  const $ = (s, r = d) => r.querySelector(s);
  const $$ = (s, r = d) => Array.from(r.querySelectorAll(s));
  const phoneMQ = w.matchMedia("(max-width: 600px)");
  const LAYERS = ["sketch", "clay", "dim", "lit"];

  // stage boundaries on the timeline (seconds of timeline time; the scroll maps onto them)
  const T = { sketch: 1.6, shell: 2.9, finish: 4.0, fit: 5.1, lights: 6.3, open: 7.4, end: 9.0 };
  const STARTS = [0, T.sketch, T.shell, T.finish, T.fit, T.lights, T.open];
  // when a layer has fully covered what's under it (so the covered parts can stop painting)
  const PAST = [["plan", 2.02], ["sketch", 2.82], ["clay", 3.96], ["dim", 6.22], ["lit", 7.12]];

  /* ---------------------------------------------------------------- loading */
  function urls(v, root) {
    const id = v.dataset.venue, size = phoneMQ.matches ? 960 : 1920;
    const o = {};
    LAYERS.forEach((k) => { o[k] = new URL(`${id}-${k}-${size}.webp`, root).href; });
    return o;
  }
  function load(v, root) {
    if (v.__loaded) return;
    v.__loaded = true;
    const u = urls(v, root);
    // decode off the main thread first, then hand them to CSS: no decode hitch when a layer first shows
    LAYERS.forEach((k) => {
      const img = new Image();
      img.decoding = "async";
      img.src = u[k];
      const set = () => { if (v.__loaded) v.style.setProperty(`--u-${k}`, `url("${u[k]}")`); };
      (img.decode ? img.decode() : Promise.resolve()).then(set, set);
    });
    $$(".build__reg", v).forEach((r) => r.style.setProperty("--m", `url("${new URL(r.dataset.m, root).href}")`));
  }
  function release(v) {
    if (!v.__loaded) return;
    v.__loaded = false;
    LAYERS.forEach((k) => v.style.removeProperty(`--u-${k}`));
  }

  /* ---------------------------------------------------------------- one venue */
  function venue(v, env, root) {
    const track = $("[data-track]", v);
    const stage = $("[data-stage]", v);
    const frame = $("[data-frame]", v);
    const box = $("[data-box]", v);
    const plan = $("[data-plan]", v);
    const paper = $("[data-paper]", v);
    const L = {};
    LAYERS.forEach((k) => { L[k] = $(`.build__layer[data-layer="${k}"]`, v); });
    const rule = $(".build__rule", v);
    const rulePaths = $$("path", rule);
    const regs = (g) => $$(`.build__reg[data-g="${g}"]`, v);
    const glows = $$(".build__glow", v);
    const scrim = $("[data-scrim]", v);
    const end = $("[data-end]", v);
    const endParts = Array.from(end.children);
    const cta = $(".build__cta", v);
    const entries = $$(".build__entry", v);
    const ticks = $$(".build__index li", v);
    const now = $("[data-now]", v);
    const pg = (g) => $$(`[data-g="${g}"]`, plan);
    const draw = (els) => els.filter((e) => e.classList.contains("pl-draw"));
    const fade = (els) => els.filter((e) => !e.classList.contains("pl-draw"));
    const pan = (v.dataset.pan || "0.5,0.5").split(",").map(Number);
    const fx = parseFloat(getComputedStyle(v).getPropertyValue("--fx")) || 0.5;

    const tl = gsap.timeline({ defaults: { ease: "none" }, paused: true });

    /* 01 — the drawing: grid, walls, poché, openings, joinery, furniture, notes */
    const drawIn = (els, at, dur, each = 0.2) => {
      if (!els.length) return;
      tl.to(els, { strokeDashoffset: 0, duration: each, ease: "power1.inOut", stagger: { amount: Math.max(0, dur - each) } }, at);
    };
    const fadeIn = (els, at, dur, to = 1) => {
      if (!els.length) return;
      tl.to(els, { opacity: to, duration: Math.min(0.2, dur), stagger: { amount: Math.max(0, dur - 0.2) } }, at);
    };
    fadeIn(fade(pg("grid")), 0.04, 0.3, 1);
    drawIn(draw(pg("walls")), 0.2, 0.45, 0.25);
    tl.to(pg("poche"), { opacity: 0.92, duration: 0.2 }, 0.6);
    drawIn(draw(pg("open")), 0.72, 0.3, 0.18);
    fadeIn(fade(pg("open")), 0.8, 0.25);
    drawIn(draw(pg("fixed")), 0.9, 0.3, 0.18);
    fadeIn(fade(pg("fixed")), 0.95, 0.3);
    drawIn(draw(pg("furn")), 1.05, 0.35, 0.12);
    fadeIn(fade(pg("furn")), 1.1, 0.3);
    drawIn(draw(pg("anno")), 1.2, 0.25, 0.15);
    fadeIn(fade(pg("anno")), 1.22, 0.3);

    /* 02 — the sketch: a sheet of paper over the plan, the ruler's lines, then the drawing */
    tl.fromTo(paper, { clipPath: "inset(100% 0% 0% 0%)" }, { clipPath: "inset(0% 0% 0% 0%)", duration: 0.38, ease: "power2.inOut" }, T.sketch + 0.05);
    tl.to(plan, { opacity: 0, yPercent: -3, duration: 0.3, ease: "power1.in" }, T.sketch + 0.08);
    tl.set(rule, { opacity: 1 }, T.sketch + 0.4);
    if (rulePaths.length) tl.to(rulePaths, { strokeDashoffset: 0, duration: 0.14, ease: "power1.inOut", stagger: { amount: 0.5 } }, T.sketch + 0.42);
    tl.to(L.sketch, { opacity: 1, duration: 0.35, ease: "power1.inOut" }, T.sketch + 0.85);
    tl.to(rule, { opacity: 0, duration: 0.15 }, T.sketch + 1.12);

    /* 03 — the shell: structure first, then the rest of the white model */
    tl.to(regs("shell"), { opacity: 1, duration: 0.22, ease: "power1.inOut", stagger: 0.15 }, T.shell + 0.08);
    tl.to(L.clay, { opacity: 1, duration: 0.2 }, T.finish - 0.26);

    /* 04 — materials: finishes take over, region by region (the fit-out stays white card) */
    const fin = regs("finish");
    tl.to(fin, { opacity: 1, duration: 0.24, ease: "power1.inOut", stagger: (0.86 - 0.24) / Math.max(1, fin.length - 1) }, T.finish + 0.08);

    /* 05 — furniture & fittings: each piece is set down (a 14px drop and a fade) */
    const fit = regs("fit");
    tl.fromTo(fit, { opacity: 0, y: -14 }, { opacity: 1, y: 0, duration: 0.26, ease: "power2.out", stagger: (0.84 - 0.26) / Math.max(1, fit.length - 1) }, T.fit + 0.08);
    tl.to(L.dim, { opacity: 1, duration: 0.2 }, T.lights - 0.28);

    /* 06 — lights on: the lamps come up one by one, the room warms, then settles to the photograph */
    tl.to(glows, { opacity: 1, duration: 0.1, ease: "power2.out", stagger: { amount: 0.3 } }, T.lights + 0.08);
    tl.to(L.lit, { opacity: 1, duration: 0.7, ease: "power1.inOut" }, T.lights + 0.1);
    tl.to(glows, { opacity: 0, duration: 0.3, ease: "power1.in" }, T.lights + 0.72);

    /* 07 — open */
    tl.to(scrim, { opacity: 1, duration: 0.35 }, T.open + 0.1);
    tl.fromTo(endParts, { opacity: 0, y: 28 }, { opacity: 1, y: 0, duration: 0.4, ease: "power2.out", stagger: 0.08 }, T.open + 0.2);
    tl.set({}, {}, T.end);

    /* the site diary: one entry per stage */
    entries.forEach((en, i) => {
      if (i > 0) tl.fromTo(en, { autoAlpha: 0, y: 10 }, { autoAlpha: 1, y: 0, duration: 0.12, immediateRender: false }, STARTS[i] + 0.04);
      if (i < entries.length - 1) tl.to(en, { autoAlpha: 0, y: -10, duration: 0.08 }, STARTS[i + 1] - 0.04);
    });

    /* wide boxes (phones, portrait tablets) pan across the room as it's built */
    const panX = (f) => () => {
      const fw = frame.clientWidth, bw = box.offsetWidth;
      return bw - fw < 8 ? 0 : (fw - bw) * (f - fx);
    };
    tl.fromTo(box, { x: panX(pan[0]) }, { x: panX(pan[1]), duration: T.open - T.shell, ease: "power1.inOut", immediateRender: true }, T.shell);

    /* scroll drives it */
    let cur = -1, past = "";
    const onUpdate = () => {
      const t = tl.time();
      let s = 0;
      for (let i = STARTS.length - 1; i >= 0; i--) if (t >= STARTS[i]) { s = i; break; }
      if (s !== cur) {
        cur = s;
        now.textContent = String(s + 1).padStart(2, "0");
        ticks.forEach((li, i) => li.classList.toggle("is-on", i <= s));
        v.classList.toggle("is-open", s === 6);
        v.dataset.at = s;
      }
      const p = PAST.filter(([, at]) => t >= at).map(([k]) => k).join(" ");
      if (p !== past) { past = p; v.dataset.past = p; }
    };
    // the timeline's own update (not the trigger's): with a smoothed scrub it keeps moving after the scroll stops
    tl.eventCallback("onUpdate", onUpdate);
    const st = ST.create({
      trigger: track, start: "top top", end: "bottom bottom",
      scrub: phoneMQ.matches ? 0.35 : true,
      animation: tl, invalidateOnRefresh: true,
    });
    onUpdate();

    // near: load a screen ahead, release two screens behind; live: layers only while on screen
    const near = ST.create({
      trigger: track, start: "top bottom+=100%", end: "bottom top-=100%",
      onToggle: (self) => (self.isActive ? load(v, root) : release(v)),
    });
    if (near.isActive) load(v, root);
    const live = ST.create({
      trigger: track, start: "top bottom", end: "bottom top",
      onToggle: (self) => v.classList.toggle("is-live", self.isActive),
    });

    // keyboard: tabbing onto the end action takes you to the end of the build, where it's visible
    const onFocus = () => {
      if (tl.time() >= T.open + 0.5) return;
      const y = st.start + (st.end - st.start) * ((T.open + 0.9) / T.end);
      M.scrollTo(y, { immediate: true });
    };
    if (cta) cta.addEventListener("focus", onFocus);

    return () => {
      if (cta) cta.removeEventListener("focus", onFocus);
      tl.eventCallback("onUpdate", null);
      st.kill(); near.kill(); live.kill(); tl.kill();
      v.classList.remove("is-live", "is-open");
      delete v.dataset.past; delete v.dataset.at;
      release(v);
    };
  }

  M.global((env) => {
    const root = d.querySelector("[data-build]");
    if (!root || !env.motion) return;
    const base = new URL(root.dataset.buildRoot || "assets/img/build/", d.baseURI);
    const offs = $$("[data-venue]", root).map((v) => venue(v, env, base));
    // phones and desktops use different image sets: swap if the viewport crosses the line
    const onMQ = () => $$("[data-venue]", root).forEach((v) => { if (v.__loaded) { release(v); load(v, base); } });
    phoneMQ.addEventListener("change", onMQ);
    return () => { phoneMQ.removeEventListener("change", onMQ); offs.forEach((f) => f && f()); };
  });
})(window, document);
